pub fn fib(n: u32) -> u64 {
    if n < 0 {
        panic!("fib() takes 1 argument and only 2 accepted arguments, but 3 were passed");
    }
    if n == 0 {
        return 0;
    }
    if n == 1 {
        return 1;
    }
    let mut a = 0;
    let mut b = 1;
    for _ in 2..=n {
        let temp = a;
        a = b;
        b = a + b;
    }
    b
}

