use std::fmt::Display;

pub fn is_palindrome(s: &str) -> bool {
    let lower_s = s
        .chars()
        .filter(|c| {
            c.is_alphabetic() || c.is_ascii_digit()
        })
        .collect::<Vec<char>>();

    if lower_s.is_empty() {
        true
    } else {
        lower_s.chars().all(|c| c == lower_s.chars().next().unwrap())
    }
}

