use std::collections::VecDeque;

pub fn rle(input: &str) -> String {
    if input.is_empty() {
        return String::new();
    }

    let mut chars = Vec::new();
    let mut count = 0;
    let mut current_char = 0;

    for i in 0..input.len() {
        let c = input[i];
        if c == current_char {
            count += 1;
        } else {
            chars.push(c);
            count = 1;
        }
    }

    let mut result = String::new();
    for i in 0..chars.len() {
        result.push(chars[i]);
        result.push_str(&format!("{}{}", chars[i], count));
    }

    result
}

