pub fn word_count(text: &str) -> std::collections::HashMap<String, usize> {
    let words: Vec<String> = text
        .split_whitespace()
        .filter(|s| !s.is_empty())
        .collect();

    words.iter().map(|word| {
        word.to_lowercase().into()
    }).collect::<HashMap<String, usize>>()
}

