use std::ops::RangeBounds;

/// Returns n! or None when the result does not fit in u64.
pub fn factorial(n: u32) -> Option<u64> {
    // Base case: 0! = 1
    if n == 0 {
        return Some(1);
    }

    // Base case: 1! = 1
    if n == 1 {
        return Some(1);
    }

    // Recursive step: n! = n * (n-1)!
    // We need to check if the result fits in u64
    let mut result = 1u64;
    let mut current = n;
    while current > 0 {
        result *= current;
        if result > u64::MAX as u64 {
            return None;
        }
        current -= 1;
    }

    Some(result)
}

