use std::ops::RangeBounds;

/// Returns the largest sum of a contiguous, non-empty run of elements.
/// 
/// # Arguments
/// * `v` - The input slice of integers
/// 
/// # Returns
/// * The largest sum of a contiguous, non-empty run of elements
/// 
/// # Examples
/// 
/// ```
/// let v: Vec<i64> = vec![1, 2, 3, 4, 5];
/// let result = max_subarray(&v);
/// println!("Max subarray: {}", result); // 10
/// ```
pub fn max_subarray(v: &[i64]) -> i64 {
    if v.is_empty() {
        return 0;
    }

    let mut max_sum = v[0];

    for &x in v.iter().skip(1) {
        let current_sum = max_sum + x;
        let new_max = max_sum.max(current_sum);
        max_sum = new_max;
    }

    max_sum
}

