use std::cmp::Ordering;

pub fn find(v: &[i32], target: i32) -> Option<usize> {
    let mut low = 0;
    let mut high = v.len();
    let mut left = 0;
    let mut right = 0;

    while low < high {
        let mid = (low + high) / 2;
        if v[mid] == target {
            return Some(mid);
        } else if v[mid] < target {
            left = mid + 1;
        } else {
            right = mid;
        }
    }

    if left < high {
        Some(left)
    } else {
        None
    }
}

