use std::fmt::Display;

pub fn to_binary(n: u32) -> String {
    if n == 0 {
        "0".to_string()
    } else {
        let mut result = String::new();
        while n > 0 {
            result.push_str(&format!("{:0b}", n));
            n >>= 1;
        }
        result
    }
}

