use std::ops::Range;

/// Counts the steps of the Collatz sequence from n to 1
/// An even number is halved, an odd number becomes 3n + 1
/// collatz_steps(1) is 0
/// n is at least 1
pub fn collatz_steps(n: u64) -> u32 {
    // Handle edge case
    if n == 0 {
        return 0;
    }
    if n == 1 {
        return 0;
    }

    let mut steps = 0;
    while n > 1 {
        if n % 2 == 0 {
            // Even number: halved
            steps += 1;
            n /= 2;
        } else {
            // Odd number: multiply by 3 and add 1
            steps += 1;
            n = 3 * n + 1;
        }
    }

    steps
}

