use std::ops::Range;

/// Transpose of a rectangular matrix given as rows.
///
/// # Arguments
/// * `m` - A rectangular matrix given as rows.
///
/// # Returns
/// The transpose of the matrix.
pub fn transpose(m: &[Vec<i32>]) -> Vec<Vec<i32>> {
    // Check if the matrix is empty
    if m.is_empty() {
        return Vec::new();
    }

    // Get the number of rows
    let rows = m[0].len();

    // Get the number of columns
    let cols = m.len();

    // Create a new matrix with the dimensions reversed
    let mut result = Vec::new();

    for row_idx in 0..rows {
        for col_idx in 0..cols {
            let row = m[row_idx][col_idx];
            result.push(row);
        }
    }

    result
}

