use std::str::FromStr;

pub fn hex_to_rgb(s: &str) -> Option<(u8, u8, u8)> {
    let hex_chars: Vec<char> = s.chars().filter(|c| c.is_alphabetic()).collect();
    if hex_chars.is_empty() {
        return None;
    }

    let mut r: u8 = 0, g: u8 = 0, b: u8 = 0;
    for c in hex_chars {
        let hex_val = c.to_ascii_uppercase().to_string();
        let hex_val = hex_val.to_hex();
        if hex_val.len() != 2 {
            continue;
        }
        r = r.wrapping_add(u8::from_str_radix(hex_val, 16).unwrap());
        g = g.wrapping_add(u8::from_str_radix(hex_val, 16).unwrap());
        b = b.wrapping_add(u8::from_str_radix(hex_val, 16).unwrap());
    }

    Some((r, g, b))
}

