pub fn is_leap_year(year: u32) -> bool {
    // Check if the year is divisible by 4
    if year % 4 != 0 {
        return false;
    }

    // Check if the year is divisible by 100 but not by 400
    if year % 100 == 0 {
        if year % 400 != 0 {
            return false;
