use std::fmt;

pub fn rotate_left(v: &[i32], k: usize) -> Vec<i32> {
    // Handle empty slice
    if v.is_empty() {
        return Vec::new();
    }

    // Handle k > length
    if k > v.len() {
        return v.clone();
    }

    // Calculate the number of elements to rotate
    let to_rotate = k % v.len();

    // Create a new slice with the first k elements
    let mut rotated = Vec::with_capacity(k);
    for i in 0..k {
        rotated.push(v[i]);
    }

    // Copy the remaining elements
    for i in k..v.len() {
        rotated.push(v[i]);
    }

    rotated
}

